/**
 * Publication is a collection published at a public address, as this device remembers it. It is a
 * copy: the server issues the address and keeps the page, and this is its last answer, so a window
 * can draw a published collection before asking anything.
 */
export interface Publication {
    "options"?: PublicationOptions | null;
    "collectionId": string;

    /**
     * WorkspaceID is the workspace the collection lives in, which is where the window's list of pages
     * asks for it.
     */
    "workspaceId"?: string;

    /**
     * ID is the server's row. Empty until a publish has been answered.
     */
    "id"?: string;

    /**
     * Slug is the last segment of the address, and URL the whole of it to hand out.
     */
    "slug"?: string;
    "url"?: string;
    "visibility"?: string;
    "status"?: string;
    "revision"?: number;

    /**
     * ContentHash is the digest of what was published, so that a device can say whether the page is
     * behind what it holds without publishing to find out.
     */
    "contentHash"?: string;
    "environmentName"?: string;
    "updatedAt"?: number;

    /**
     * CanManage is the server's answer about the caller who asked, and never about the row.
     */
    "canManage": boolean;

    /**
     * PendingUnpublish marks a takedown that has not reached the server yet — the one thing here that
     * is this device's own state rather than the server's.
     */
    "pendingUnpublish"?: boolean;

    /**
     * Outline and Changes are this device's own state: the shape of the last publish and what has
     * changed since. No server answer carries them, so a dedicated save writes them and every other
     * write of the row leaves them alone.
     */
    "outline"?: OutlineItem[] | null;
    "changes"?: PageRelease[] | null;
}

export interface PublicationDetails {
    "views": number;
    "imports": number;
    "versions": PublicationVersion[] | null;
}

export interface PublicationOptions {
    "docs": boolean;
    "examples": boolean;
}

export interface PublicationVersion {
    "revision": number;
    "publishedAt": number;
    "environmentName": string;
    "requests": number;
    "restoredFrom": number;
}

/**
 * QueueStatus defines outbox queue item processing state.
 */
export enum QueueStatus {
    /**
     * The Go zero value for the underlying type of the enum.
     */
    $zero = "",

    QueuePending = "pending",
    QueueSending = "sending",
    QueueFailed = "failed",
    QueueParked = "parked",
};

/**
 * QueuedChange represents UI-friendly outbox entry description.
 */
export interface QueuedChange {
    "kind": EntityType;
    "entityId": string;
    "action": Action;
    "status": QueueStatus;
    "attempts": number;
    "name"?: string;
    "reason"?: string;
    "retryAt"?: number;
}

/**
 * Reading is a way a value reads beyond its text: a token, a moment, a colour.
 */
export interface Reading {
    /**
     * Kind names the reading ("jwt", "timestamp", "uuid"); the window words it.
     */
    "kind": string;

    /**
     * Rows are the facts found.
     */
    "rows": ReadingRow[] | null;

    /**
     * Nested is a document found inside the value, formatted.
     */
    "nested"?: string;
}

/**
 * ReadingRow is one fact of a reading. Value is data, never a sentence; Key is worded by the
 * window.
 */
export interface ReadingRow {
    "key": string;
    "value": string;

    /**
     * Shape says how to draw Value: "text", "code", "time" (RFC 3339) or "colour".
     */
    "shape": string;
}

/**
 * Record represents full execution history, including timing phases, headers, and bodies.
 */
export interface Record {
    "id": string;
    "workspaceId"?: string;
    "source": RecordSource;
    "method": string;
    "url": string;
    "status": number;
    "statusText": string;
    "contentType"?: string;
    "error"?: string;
    "durationUs": number;
    "startedAt": number;
    "nodeId"?: string;

    /**
     * RunID is the collection run this record was sent by, empty for a request sent on its own. The
     * run travels as a document of its own, and the record names it rather than carrying a copy.
     */
    "runId"?: string;

    /**
     * Agent is who sent this through the MCP server when it was not the person. Empty for sends
     * made by the window, a run or the command line.
     */
    "agent"?: string;
    "tabId"?: number;
    "tabTitle"?: string;
    "tabURL"?: string;
    "favIconUrl"?: string;
    "isRemote"?: boolean;
    "cancelled"?: boolean;
    "dnsUs"?: number | null;
    "connectUs"?: number | null;
    "tlsUs"?: number | null;
    "waitUs"?: number | null;
    "downloadUs"?: number | null;
    "requestBytes"?: number;
    "responseBytes"?: number;
    "requestHeaders": HeaderPair[] | null;
    "responseHeaders": HeaderPair[] | null;
    "cookieWrites"?: CookieWrite[] | null;
    "requestBody"?: BodyRef | null;
    "responseBody"?: BodyRef | null;
    "skipped"?: boolean;
}

/**
 * RecordSource defines the origin of a request record (manual builder or browser extension).
 */
export enum RecordSource {
    /**
     * The Go zero value for the underlying type of the enum.
     */
    $zero = "",

    SourceManual = "manual",
    SourceBrowser = "browser",
};

