export interface ResponseExample {
    "name"?: string;
    "status"?: number;
    "body"?: string;
    "headers"?: HeaderPair[] | null;
}

export enum Retention {
    /**
     * The Go zero value for the underlying type of the enum.
     */
    $zero = "",

    RetainWeek = "7",
    RetainMonth = "30",
    RetainForever = "forever",
};

/**
 * Role is a named set of permissions. The application does not write these — an organisation does,
 * in the panel — so what is here is enough to draw a list and to send one back.
 */
export interface Role {
    "id": string;
    "name": string;

    /**
     * Description is what the role is for, which the window may show under the name.
     */
    "description"?: string;

    /**
     * BuiltIn is one of the four the product ships. They are held out for reading and handing out,
     * never edited, and the window draws them as words rather than as somebody's own naming.
     */
    "builtIn"?: boolean;
}

/**
 * Root is one authority somebody added, with the name it is shown under.
 */
export interface Root {
    "name": string;
    "pem": string;
}

export interface Row {
    "id": string;
    "name": string;
    "value": string;
    "enabled": boolean;
    "description"?: string;
}

export enum RowKind {
    /**
     * The Go zero value for the underlying type of the enum.
     */
    $zero = "",

    RowParams = "params",
    RowHeaders = "headers",
    RowForm = "form",
    RowPathParams = "pathParams",
};

export interface Scheme {
    "type": AuthType;
    "label": string;
    "menu"?: string;
    "where"?: string;
    "sends"?: string;
    "note"?: string;
    "fields": Field[] | null;
    "primary": boolean;
    "needsParent"?: boolean;
    "fetches"?: boolean;
}

/**
 * ScriptLog is one line a script printed. The level is the call it came from, so a warning does not
 * have to be spelled out in the text.
 */
export interface ScriptLog {
    "level": string;
    "message": string;
}

/**
 * ScriptRun is one execution of one script: what ran, whether it went through, what it printed and
 * what it asserted. A run that failed is still a run — the failure is what the tab has to show.
 */
export interface ScriptRun {
    "id": string;
    "recordId"?: string;
    "nodeId"?: string;
    "scope": ScriptScope;
    "error"?: string;
    "logs": ScriptLog[] | null;
    "tests": TestResult[] | null;
    "durationUs": number;
    "createdAt": number;
    "ok": boolean;
    "skipRequest"?: boolean;
}

/**
 * ScriptScope is when a script ran: before the request was sent, or after the answer came back.
 */
export enum ScriptScope {
    /**
     * The Go zero value for the underlying type of the enum.
     */
    $zero = "",

    ScriptPre = "pre",
    ScriptPost = "post",
};

/**
 * Scripts is the code that runs around a request: before it goes out and after it comes back. On a
 * node it is a pointer like Auth (nil means not set here), but levels do not override each other:
 * every level with a script runs, outermost first.
 */
export interface Scripts {
    "pre"?: string;
    "post"?: string;

    /**
     * A half can be switched off without losing its code. An off half is still an answer about its
     * level, so it keeps the level in the chain.
     */
    "preOff"?: boolean;
    "postOff"?: boolean;

    /**
     * Captures run before the level's own code, so the code can read what they store.
     */
    "captures"?: Capture[] | null;
}

/**
 * SearchGroup is one area's answer: the rows to draw and how many the area found before the list
 * was cut. The heading counts matches, not shown rows.
 */
export interface SearchGroup {
    "kind": SearchKind;
    "total": number;
    "hits": SearchHit[] | null;
}

/**
 * SearchHit is one row of the palette. Everything but the words is decided here: title and path are
 * the user's text and the note is a shape the window words. Only where the query was found is
 * carried, not the matched text, which keeps a variable's value out of the answer.
 */
export interface SearchHit {
    "kind": SearchKind;
    "id": string;
    "title": string;

    /**
     * Path is what the row sits inside, outermost first: the collections above a request. The window
     * joins it with its own separator, so the separator is not a word Go has to own.
     */
    "path": string[] | null;
    "badge"?: string;
    "note": SearchNote;
    "match": SearchMatch;

    /**
     * At is when the row happened, in milliseconds, or 0 for a row that did not happen — a saved
     * request has no time, and the window draws none rather than one it made up.
     */
    "at": number;
    "open": SearchOpen;
}

/**
 * SearchKind names one area of the index. The window draws a group and a chip per kind and words
 * both from its catalogue. The set is open: an area is a method on the index plus a value here.
 */
export enum SearchKind {
    /**
     * The Go zero value for the underlying type of the enum.
     */
    $zero = "",

    SearchRequest = "request",
    SearchCollection = "collection",
    SearchEnvironment = "environment",
    SearchHistory = "history",
    SearchAction = "action",
};

/**
 * SearchMatch is where the query was found, which orders the results: exact name, then name, then
 * address, then a variable that merely holds the word. It is a tier rather than a score;
 * SearchHit.At breaks ties within a tier.
 */
export enum SearchMatch {
    /**
     * The Go zero value for the underlying type of the enum.
     */
    $zero = 0,

    /**
     * MatchNone is the zero value, and it is deliberately not a tier: a row that matched nothing must
     * not read as one that matched exactly when somebody forgets to look at the flag beside it.
     */
    MatchNone = 0,

    /**
     * MatchExact is the whole name, character for character. It is separated from MatchName because
     * it is the one case where the user has already typed what they want and the row is the answer.
     */
    MatchExact = 1,
    MatchName = 2,
    MatchPath = 3,
    MatchValue = 4,
};

/**
 * SearchNote is that line: which shape it is, and the number it counts when it counts one.
 */
export interface SearchNote {
    "kind": SearchNoteKind;
    "count"?: number;
}

/**
 * SearchNoteKind is what a row says on its right, as a shape rather than a sentence ("current", "8
 * requests"). The window words it from its catalogue.
 */
export enum SearchNoteKind {
    /**
     * The Go zero value for the underlying type of the enum.
     */
    $zero = "",

    /**
     * The zero value is the row with no note, so it needs no constant of its own.
     */
    NoteActive = "active",
    NoteRequests = "requests",
};

/**
 * SearchOpen is where a row takes the window: the verb, the id, and — for a variable, which is the
 * one thing that is addressed through the environment holding it — the scope to open.
 */
export interface SearchOpen {
    "target": SearchTarget;
    "id": string;
    "scope"?: string;
}

/**
 * SearchResult is the whole answer, one group per area that found something, in display order. An
 * area that found nothing is absent rather than empty.
 */
export interface SearchResult {
    "groups": SearchGroup[] | null;
}

/**
 * SearchTarget names what activating a row does. The window switches on it; a target this build
 * does not know is a row that does nothing, which is what a newer build's answer should be to an
 * older window.
 */
export enum SearchTarget {
    /**
     * The Go zero value for the underlying type of the enum.
     */
    $zero = "",

    TargetRequest = "request",
    TargetCollection = "collection",
    TargetEnvironment = "environment",
    TargetVariable = "variable",
    TargetHistory = "history",
};

